/**
 * Every in-app route, built in one place so no screen assembles a path by hand.
 *
 * Ids are encoded, so an id that is not a clean slug can never change which route
 * is opened. The result is cast to `Href` because Expo Router's typed routes are
 * generated by running the dev server or an export; a hand-written cast keeps the
 * type check independent of that generated file.
 */

import type { Href } from 'expo-router';

const href = (path: string): Href => path as Href;
const id = encodeURIComponent;

export const routes = {
  home: (): Href => href('/'),
  scan: (): Href => href('/scan'),
  pair: (tableId: string, token: string): Href =>
    href(`/pair?tableId=${id(tableId)}&token=${id(token)}`),
  diagnostics: (): Href => href('/diagnostics'),
  table: (tableId: string): Href => href(`/t/${id(tableId)}`),
  design: (tableId: string, designId: string): Href =>
    href(`/t/${id(tableId)}/designs/${id(designId)}`),
  job: (tableId: string, jobId: string): Href => href(`/t/${id(tableId)}/jobs/${id(jobId)}`),
  result: (tableId: string, jobId: string): Href =>
    href(`/t/${id(tableId)}/jobs/${id(jobId)}/result`),
};
